import { HttpClient, HttpErrorResponse, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Email, EmailRes } from '../interfaces/pdf.interface';
import { firstValueFrom, Observable } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { of } from 'rxjs';
import { environment } from '../../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class EmailService {
  constructor(private http: HttpClient) { }
  async getEmailparser(nId: string, nCaseid: string): Promise<EmailRes> {
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.post<EmailRes>(
          `${environment.uploadservice}/fileconvert/email_parse`, { 'nBundledetailid': nId, nCaseid: nCaseid }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }


  async getAttechment(path: string, id: number): Promise<Blob> {
    let params = new HttpParams().set('cPath', path).set('nId', id.toString()); // Ensure `id` is passed as a string

    let res: Blob;
    try {
      res = await firstValueFrom(
        this.http.get<Blob>(`${environment.cloudUrl}${environment.coreservice}/email/getattechment`, {
          params: params,
          responseType: 'blob' as 'json', // Ensure we receive the response as a Blob
        })
      );
    } catch (error) {
      console.error('Error fetching attachment:', error);
      res = null;
    }
    return res;
  }


  async checkFileExists(url: string): Promise<boolean> {
    try {
      const response = await this.http.head(url).toPromise();
      return true;
    } catch (error) {
      if (error instanceof HttpErrorResponse) {
        // 404 means file doesn't exist
        return false;
      }
      // For other errors, throw to be caught by caller
      throw error;
    }
  }

  async getFileUrl(cPath: string): Promise<any> {
    try {
      const res = await firstValueFrom(
        this.http.get<any>(`${environment.uploadservice}/fileconvert/get-file-url`, {
          params: { cPath: cPath }
        })
      );
      debugger;
      return res;
    } catch (error) {
      if (error instanceof HttpErrorResponse) {
        // 404 means file doesn't exist
        console.error('File not found:', error);
        return {};
      }
    }
  }


}
