import { ChangeDetectorRef, Component, Input } from '@angular/core';
import { DocInfo } from '../../../pdf/interfaces/pdf.interface';
import { PdfDataService } from '../../../pdf/service/pdf-data.service';
import { NgxExtendedPdfViewerModule } from 'ngx-extended-pdf-viewer';
import { environment } from '../../../../environments/environment';
import { ActivatedRoute } from '@angular/router';
import { pdfDefaultOptions } from 'ngx-extended-pdf-viewer';
import { DocViewerComponent } from '../../../pdf/components/doc-viewer/doc-viewer.component';

@Component({
  selector: 'quickpdf',
  standalone: true,
  imports: [NgxExtendedPdfViewerModule, DocViewerComponent],
  templateUrl: './quickpdf.component.html',
  styleUrl: './quickpdf.component.scss'
})
export class QuickpdfComponent {
  filetypes = ['document', 'video', 'video', 'ppt', 'pptx', 'msg', 'pdf']
  filetype: string = '';
  onPage: number = 1;
  nBundledetailid: string;
  docInfo: DocInfo | null = {} as DocInfo;
  filepath: string = environment.documentStorage;
  pdfSrc: string;
  loadingStats: 'L' | 'F' | 'C' = 'L'; // 'L' for loading, 'F' for failed, 'C' for loading completed
  loadingProgress: number = 0;

  pdfLoaded: boolean;
  pdfFailed: boolean;
  nCaseid: string;
  constructor(private pdfData: PdfDataService, private cdr: ChangeDetectorRef, private route: ActivatedRoute) {
    const params: any = this.route.snapshot.params;
    if (params) {
      this.nBundledetailid = params["id"];
      this.onPage = this.route.snapshot.queryParams["nPage"] || 1;
      this.nCaseid = this.route.snapshot.queryParams["nCaseid"] || null;
      this.initData();
    }
  }

  async initData() {
    pdfDefaultOptions.doubleTapZoomsInHandMode = false;
    // pdfDefaultOptions.doubleTapZoomsInText
    const data = await this.pdfData.fetchDocInfo(this.nBundledetailid);
    this.docInfo = Object.assign(this.docInfo, data);
    debugger;
    this.filetype = this.getFileType(this.docInfo.cPath);
    this.pdfSrc = `${this.filepath}${this.docInfo.cPath}${(this.docInfo?.version ? ('?VersionId=' + this.docInfo?.version) : '')}`;
    if (this.filetype != 'pdf') {
      this.pdfLoaded = true;
    }
    this.loadingStats = 'C';
    this.cdr.detectChanges();

  }

  onProgress(e: any) {
    // console.log('Progress', e?.percent);
    this.loadingProgress = parseInt(e.percent);
    this.cdr.detectChanges();
  }

  onPdfLoadingStart(e: any) {
    this.pdfLoaded = false;
    this.pdfFailed = false;
  }

  onPdfLoadingFailed(e: any) {
    console.error('PDF Failed', e);
    this.pdfFailed = true;
    this.cdr.detectChanges();
  }



  OnPageLoad(e: any) {
    this.pdfLoaded = true;
    this.cdr.detectChanges();
  }

  onOpen() {
    const message = { event: 'ON-INDIVIDUAL', type: 'QUICK-VIEW' };
    window.parent.postMessage(message, window.location.origin);
  }


  getFileType(path: string): string {
    const videoExtensions = ['mp4', 'avi', 'mov', 'wmv', 'flv'];
    const pdfExtensions = ['pdf'];
    const imageExtensions = ['jpeg', 'jpg', 'png', 'gif', 'bmp', 'svg'];
    const documentExtensions = ['doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'dwg', 'xlsm'];
    const emailExtensions = ['msg'];

    const ext = path.split('.').pop().toLowerCase();

    if (videoExtensions.includes(ext)) {
      return 'video';
    } else if (imageExtensions.includes(ext)) {
      return 'image';
    } else if (documentExtensions.includes(ext)) {
      return 'document';
    } else if (emailExtensions.includes(ext)) {
      return 'msg';
    } else if (pdfExtensions.includes(ext)) {
      return 'pdf';
    } else {
      return 'unknown';
    }
  }
}
