import { Component, ElementRef, EventEmitter, Input, Output, ViewChild, OnInit } from '@angular/core';
import { environment } from '../../../../environments/environment';
import { PdfDataService } from '../../service/pdf-data.service';
import { ViewerModule } from '../../modules/shared/imageShared.moduls';
import { DocInfo, Email, EmailRes, highlightModeType, toolEvents } from '../../interfaces/pdf.interface';
import { DOC_VIEWER_STATIC, DOC_VIEWER_EVENTS } from '../../interfaces/doc-viewer.constants';
import { EmailService } from '../../service/email.service';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { TranslateModule } from '@ngx-translate/core';
import { MatTooltipModule } from '@angular/material/tooltip';
import { CommonModule } from '@angular/common';
import { ImgComponent } from '../../../shared/components/img/img.component';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { NetworkStatusService } from '../../../shared/services/network-status/network-status.service';
import { ButtonComponent } from "../../../shared/components/button/button.component";
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';

@Component({
  selector: 'doc-viewer',
  standalone: true,
  imports: [CommonModule, ViewerModule, IconComponent, ImgComponent, ButtonComponent, TranslateModule, MatTooltipModule],
  templateUrl: './doc-viewer.component.html',
  styleUrl: './doc-viewer.component.scss'
})
export class DocViewerComponent implements OnInit {
  @ViewChild('htmlIframe') iframeRef!: ElementRef;
  sanitizedBody: SafeHtml | null = null;
  safeUrl: SafeHtml | null = null;
  // docUrl: string;
  isSmall_pdf = false;
  @Input() path = '';
  @Input() fullMode = false;
  @Input() isRealtime?: unknown;
  @Input() nBundledetailid = '';
  @Input() filetype = '';
  @Input() isMyfile = false;
  @Input() nCaseid = '';
  @Input() bIsconvert = '';
  url = environment.nonPdfStorage;
  localurl = environment.documentStorage;
  downloadpath = '';
  newPath?: string;
  docUrl = '';
  @Output() viewerEvent = new EventEmitter<{ event: string; data?: unknown }>();
  isLoading = true;
  loadingProgress = 0;
  email: Email | null = null
  retryCount: number = 0;
  hasError = false;
  isOnline: boolean = true;
  @ViewChild('iframeElement', { static: true }) iframe?: ElementRef<HTMLIFrameElement>;

  @Input() docInfo?: DocInfo;
  @Input() hightlightMode?: highlightModeType;
  lastErrorMessage: string | null = null;


  constructor(private readonly pdfDataService: PdfDataService, private readonly emailservice: EmailService,
    private readonly sanitizer: DomSanitizer,
    private readonly networkStatus: NetworkStatusService) { }

  ngOnInit(): void {
    this.networkStatus.checkNetworkStatus().then(status => { this.isOnline = status; });
    this.docUrl = this.url + this.downloadpath + this.path;
    if (this.path.toUpperCase().includes('.MP3')) {
      this.filetype = 'M'
      this.isLoading = false;
    } else if (/\.(jpeg|jpg|png|gif|bmp|svg)$/i.test(this.path.toLowerCase())) {
      this.filetype = 'I';
      this.isLoading = false;
    } else if (/\.(mp4|avi|mov|wmv|flv)$/i.test(this.path.toLowerCase())) {
      this.filetype = 'V';
      this.isLoading = false;
    } else if (/\.(doc|docx|xls|xlsx|ppt|pptx|xlsm)$/i.test(this.path.toLowerCase())) {
      this.filetype = 'D';
      setTimeout(() => {
        const iframe = document.getElementById('excel-viewer') as HTMLIFrameElement | null;
        iframe?.setAttribute('src', 'https://view.officeapps.live.com/op/embed.aspx?src=' + this.docUrl);
        this.isLoading = false;
      }, 10);
      
    } else if (/\.(dwg)$/i.test(this.path.toLowerCase())) {
      this.filetype = 'D';
      setTimeout(() => {
        const iframe = document.getElementById('excel-viewer') as HTMLIFrameElement | null;
        iframe?.setAttribute('src', '//sharecad.org/cadframe/load?url=' + this.docUrl);
        this.isLoading = false;
      }, 10);
      
    } else if (/\.(msg)$/i.test(this.path.toLowerCase())) {
      this.getEmail();
    }

    // Listen for messages from the parent or other windows
    globalThis.addEventListener('message', (event: MessageEvent) => {
      if (event.data?.event === 'dblclick') {
        this.newtab();
      }
    });
  }

  async downloadAttachment(id: number, filename: string) {
    const res: Blob = await this.emailservice.getAttechment(this.path, id)
    const url = globalThis.URL.createObjectURL(res);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    globalThis.URL.revokeObjectURL(url);
  }


  onButtonClick(event: Event) {
    // Stop the event propagation to prevent it from reaching the container's dblclick
    event.stopPropagation?.();
    return true; // Return true to allow the default button action to proceed
  }

  onImageDoubleClick(event: MouseEvent) {
    event.preventDefault(); // Prevent the default fullscreen behavior
    const target = event.target as HTMLElement;

    // Check if the double-clicked element is an image
    if (target.tagName.toLowerCase() === 'img' || target.tagName.toLowerCase() === 'video') {
      const imageUrl = target.getAttribute('src');
      if (imageUrl) {
        globalThis.open(imageUrl, '_blank');
      }
    }
  }


  getFileExtension(fileName: string): string {
    if (!fileName || fileName.lastIndexOf('.') === -1) {
      return 'other'; // Return '.other' if there is no extension
    }

    const extension = fileName.substring(fileName.lastIndexOf('.') + 1).toLowerCase(); // Extract and normalize the extension

    return DOC_VIEWER_STATIC.validExtensions.includes(extension) ? extension.toUpperCase() : 'other'; // Return the extension or '.other'
  }

  newtab(attachemnt?, index?) {
    if (!attachemnt) {
      this.viewerEvent.emit({ event: DOC_VIEWER_EVENTS.OPEN_INDIVIDUAL });
    } else {
      this.viewerEvent.emit({ event: DOC_VIEWER_EVENTS.OPEN_ATTACHMENT, data: { nBundledetailid: index == 0 ? -1 : index - 1, cFilename: attachemnt.filename, cPath: attachemnt.cPath } });
    }
  }

  isShowView(path?: string): boolean {
    if (!path) return false;
    return /\.(jpeg|jpg|png|gif|bmp|svg|doc|docx|xls|xlsx|xlsm|ppt|pptx|msg|pdf)$/i.test(path.toLowerCase());
  }

  OnEventOfImg(event: toolEvents) {
    // propagate image component events to parent with original payload
    this.viewerEvent.emit(event);
  }

  sanitizedEmailbody(htmlContent: string) {
    this.sanitizedBody = this.sanitizer.bypassSecurityTrustHtml(htmlContent.replaceAll(/\n/g, ''));
  }

  closeRealtimePdf() {
    this.viewerEvent.emit({ event: DOC_VIEWER_EVENTS.CLOSE_REALTIME, data: null });
  }

  async getEmail() {
    try {
      this.isLoading = true;
      this.filetype = 'E';
      const htmlPath = this.getHtmlPath();

      const fileExists = this.bIsconvert != 'N';
      if (fileExists) {
        // If HTML file exists, load it in iframe
        this.loadWithIframe(htmlPath);
      } else {
        // If HTML doesn't exist, use API to process
        await this.processWithApi();
      }
    } catch (error) {
      this.hasError = true;
      this.lastErrorMessage = ErrorHandlerUtil.getErrorMessage(error);
      // On any error, fallback to API processing
      await this.processWithApi();
    } finally {
      this.filetype = 'E';
    }
  }

  private async processWithApi() {
    try {
      const res: EmailRes = await this.emailservice.getEmailparser(this.nBundledetailid, this.nCaseid);
      if (res?.msg === 1) {
        this.bIsconvert = 'V';
        const htmlPath = this.getHtmlPath();
        setTimeout(() => {
          this.loadWithIframe(htmlPath);
        }, 500);
        
      } else {
        this.filetype = 'E';
        this.isLoading = false;
        this.hasError = true;
      }
    } catch (error) {
      this.hasError = true;
      this.lastErrorMessage = ErrorHandlerUtil.getErrorMessage(error);
      this.filetype = 'E';
      this.isLoading = false;
    } finally {
      this.filetype = 'E';
    }
  }

  private getHtmlPath(): string {
    const dirPath = 'doc/case' + this.nCaseid;
    const fileName = this.getFileName(this.path).replace(/\.msg$/i, '.html');
    return `${dirPath}/${this.nBundledetailid}/${fileName}`;
  }

  async loadWithIframe(path: string) {
    try {
      this.retryCount = 0;
      // First check if the file exists and is accessible
      const response = await this.emailservice.getFileUrl(path);
      if (typeof response?.url === 'string') {
        this.safeUrl = this.sanitizer.bypassSecurityTrustResourceUrl(`${this.localurl}${path}`);
      } else {
        this.hasError = true;
        this.isLoading = false;
        this.lastErrorMessage = 'File not accessible';
      }

      setTimeout(() => {
        this.loadIframe();
      });

    } catch (error) {
      this.hasError = true;
      this.lastErrorMessage = ErrorHandlerUtil.getErrorMessage(error);
      this.isLoading = false;
    }
  }

  onIframeError(event: ErrorEvent) {
    this.hasError = true;
    this.isLoading = false;
    this.lastErrorMessage = event?.message ?? 'Iframe loading error';
  }
  loadIframe() {
    const iframe = document.querySelector<HTMLIFrameElement>('.html-iframe');

    if (!iframe) {
      this.hasError = true;
      this.lastErrorMessage = 'Iframe element not found';
      return;
    }

    // Load event listener
    iframe.addEventListener('load', () => {
      this.isLoading = false;
      this.retryCount = 0;
    });

    // Error event listener
    iframe.addEventListener('error', this.handleIframeError.bind(this));
  }

  handleIError() {
    this.handleIframeError();
  }

  private async handleIframeError() {
    let maxRetries = 5
    this.retryCount++;
    if (this.retryCount <= maxRetries) {
      await this.retryLoadIframe();
    } else {
      this.isLoading = false;
      this.hasError = true;
      this.lastErrorMessage = `Max retries reached. Failed to load iframe.`;
    }
  }

  private async retryLoadIframe(): Promise<boolean> {
    this.isLoading = true;
    this.hasError = false;
    // Add a small delay before retrying
    await new Promise(resolve => setTimeout(resolve, 1000));
    // Reload iframe content
    const iframe = document.querySelector<HTMLIFrameElement>('.html-iframe');
    iframe?.setAttribute('src', iframe?.src ?? '');
    return true
  }

  getDirPath(filePath: string): string {
    return filePath.substring(0, filePath.lastIndexOf('/'));
  }

  getFileName(filePath: string): string {
    const normalizedPath = filePath.replace(/\\/g, '/');
    return normalizedPath.substring(normalizedPath.lastIndexOf('/') + 1);
  }

  downloadURI(uri: string) {
    this.viewerEvent.emit({
        event: DOC_VIEWER_EVENTS.DOWNLOAD, data: { nBundledetailid: this.nBundledetailid, path: this.path }
      });
  }

  linkDoc() {
    (document.activeElement as HTMLElement | null)?.blur();
    this.viewerEvent.emit({
        event: DOC_VIEWER_EVENTS.LINK_ADDED_DOC, data: { ...this.docInfo }
      });
  }
}
